    def man(a, b, c, d):
        return abs(a - c) + abs(b - d)

    if not resources:
        return [0, 0]

    best = None  # (adv, -sd, opp_d, sd, dx, dy)
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if not ok(nx, ny):
            continue
        best_for_move = None  # (adv, -sd, opp_d, sd)
        for r in resources:
            if r is None or len(r) < 2:
                continue
            rx, ry = r[0], r[1]
            if (rx, ry) in obstacles:
                continue
            sd = man(nx, ny, rx, ry)
            od = man(ox, oy, rx, ry)
            adv = od - sd
            key = (adv, -sd, od, sd)
            if best_for_move is None or key > best_for_move:
                best_for_move = key
        if best_for_move is None:
            continue
        cand = (best_for_move[0], best_for_move[1], best_for_move[2], best_for_move[3], dx, dy)
        if best is None or cand > best:
            best = cand

    if best is None:
